#!/usr/bin/env node
// Self-test for story 549: the lane's one record per open Renovate PR, and one retry per
// head for a stalled check (https://work.haynesnetwork.com/projects/haynes-engineering/work_packages/549).
//
// WHY THIS EXISTS
// ---------------
// Since story 549 the night lane writes to GitHub in dry-run: its own record comment on each
// open Renovate PR, and Renovate's retry box on at most one PR a tick. Neither is a merge.
// The repository is public, so a comment anyone can write must never be taken for the
// lane's record, a record must carry nothing unsafe, and the retry must act on facts read at
// the moment of the write (Tom's ruling Q-548-04), within its limits. This suite covers the
// functions in night-merge.mjs with stub reads and writes (the tick itself is covered in
// lane-night-dryrun-selftest.mjs, section 6):
//   1. Renovate's retry box: read, ticked by one character, refused otherwise;
//   2. the record: projection, rendering, round trip, escaping, the content compared
//      without the tick's time, the publish check;
//   3. whose record: a forged record by another author is ignored and never edited; two of
//      the lane's own keep the oldest;
//   4. the retry's state machine: per head, per PR in 7 days, a second failure on the new
//      head blocks, Renovate clearing the box without a new head blocks, abandoned writes
//      do not count, intent and failed writes do;
//   5. the facts at the write (retryPreflight), each one refused;
//   6. the ledger: parse, prune, update;
//   7. ghWrite: the only shapes it sends (against a stub gh binary), and every refusal;
//   8. writePrRecords: write, re-read, no second write when unchanged; a refused write is
//      reported, stops the rest and is never called current; an identity mismatch halts;
//   9. runRetry: the ledger before the write, the body re-read before the write, a body or
//      head that changed in between, a pause, a failed ledger write, a failed write.
// The fix round after the review of 2aa270e4 added: F2 a workflow run not started yet (its
// github-actions check suite), F3 the fixed failure vocabulary and the private-address and
// in-cluster-name refusals, F4 a denial halts while a rate limit or a 5xx does not, F5 the
// pause before each record write, F6 an unresolved intent decided from facts, and F7 the
// re-list before a create, the author re-check before a demote and the Renovate app id.
//
// Usage: node scripts/upgrade-agent/lane-pr-records-selftest.mjs
// Requires: node 24. No network, no cluster.
import { chmodSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '../..');
const RES = join(ROOT, 'kubernetes/main/apps/upgrade-agent/shepherd/app/resources');
const L = await import(join(RES, 'lane-classify.mjs'));
const M = await import(join(RES, 'night-merge.mjs'));
const rules = L.loadRules(join(RES, 'upgrade-rules.json'));
const REPO = 'thaynes43/haynes-ops';

let fails = 0, passes = 0;
const ok = (cond, name, detail = '') => { if (cond) passes++; else { fails++; console.log(`FAIL ${name}${detail ? `\n     ${detail}` : ''}`); } };
const throws = (fn, re) => { try { fn(); return false; } catch (e) { return re.test(e.message); } };
const NOW = Date.parse('2026-11-13T07:00:00Z');
const iso = ms => new Date(ms).toISOString();
const D = 864e5;
const sha = c => c.repeat(40);

// A Renovate body as GitHub returned it for PR 4848 on 2026-11-12 (trimmed).
const BODY = ['This PR contains the following updates:', '', '| Package | Change |', '|---|---|', '| [x](https://example.invalid) | `1.0.0` → `1.0.1` |', '', '---', '',
  '♻ **Rebasing**: Whenever PR becomes conflicted, or you tick the rebase/retry checkbox.', '', '---', '',
  ' - [ ] <!-- rebase-check -->If you want to rebase/retry this PR, check this box', '', '---', '', 'This PR was generated by [Mend Renovate](https://mend.io/renovate/).', '<!--renovate-debug:eyJjcmVhdGVkSW5WZXIiOiI0NC4yMjguMCJ9-->'].join('\n');

const rcfg = M.retryConfig(rules), cfg = M.recordConfig(rules);
ok(rcfg.ok && rcfg.per_head === 1 && rcfg.per_pr === 2 && rcfg.window_days === 7 && rcfg.per_tick === 1 && rcfg.max_preflights_per_tick === 3, 'rules: night.retry is per head 1, per PR 2 in 7 days, per tick 1, at most 3 write-time reads per tick', JSON.stringify(rcfg));
ok(!M.retryConfig({ night: { retry: { ...rules.night.retry, max_preflights_per_tick: 0 } } }).ok && !M.retryConfig({ night: { retry: { ...rules.night.retry, per_tick: 2, max_preflights_per_tick: 1 } } }).ok, 'rules: max_preflights_per_tick 1 to 10 and at least per_tick');
ok(cfg.ok && cfg.author.login === 'haynes-ops-bot[bot]' && cfg.author.type === 'Bot' && cfg.marker === '<!-- upgrade-lane v1 -->', 'rules: night.pr_record names the lane identity haynes-ops-bot[bot] (Bot) and the marker', JSON.stringify(cfg));
ok(['pr', 'head', 'fingerprint', 'lane', 'class', 'reason', 'rules', 'checks', 'backup', 'preapproval', 'schedule', 'last_attempt', 'updated', 'retry', 'schema', 'terminal'].every(f => cfg.fields.includes(f)) && cfg.fields.length === 16, 'rules: the record carries exactly the design fields, schema, retry and terminal (story 593)', cfg.fields.join(','));
ok(rules.trusted_vet_authors.includes(cfg.author.login), 'rules: the record author is the trusted vet author (one bot identity)');
ok(!M.recordConfig({ night: { pr_record: { ...rules.night.pr_record, author: { login: 'haynes-ops-bot', type: 'User' } } } }).ok, 'rules: an author without [bot] or not a Bot is refused');
ok(!M.retryConfig({ night: { retry: { ...rules.night.retry, per_head: 2 } } }).ok && !M.retryConfig({ night: { retry: { ...rules.night.retry, per_tick: 9 } } }).ok, 'rules: per_head other than 1, or per_tick over 3, is refused');

// ── 1. the retry box ──────────────────────────────────────────────────────────
{
  ok(L.retryBox(BODY).state === 'unticked', 'box: the Renovate body reads unticked');
  const t = M.tickRetryBox(BODY);
  ok(t.ok && L.retryBox(t.body).state === 'ticked' && t.body.length === BODY.length && [...BODY].filter((c, i) => c !== t.body[i]).length === 1, 'box: ticking changes exactly one character');
  ok(t.body.includes(' - [x] <!-- rebase-check -->If you want'), 'box: the line reads - [x]');
  ok(!M.tickRetryBox(t.body).ok, 'box: an already ticked box is not ticked again');
  ok(L.retryBox(BODY.replace(' - [ ] <!-- rebase-check -->', '')).state === 'absent' && !M.tickRetryBox(BODY.replace(' - [ ] <!-- rebase-check -->', '')).ok, 'box: no box, no tick');
  ok(L.retryBox(`${BODY}\n - [ ] <!-- rebase-check -->again`).state === 'ambiguous', 'box: two boxes are ambiguous');
  ok(L.retryBox(BODY.replace(' - [ ] <!-- rebase-check -->', 'see <!-- rebase-check -->')).state === 'ambiguous', 'box: the marker on a line that is not a checkbox is ambiguous');
  ok(L.retryBox(BODY.replace(/\n/g, '\r\n')).state === 'unticked' && M.tickRetryBox(BODY.replace(/\n/g, '\r\n')).ok, 'box: CRLF bodies tick the same way');
}

// ── 2. the record ─────────────────────────────────────────────────────────────
const baseRec = (o = {}) => ({ schema: 'haynes.upgrade-lane/v1', pr: 4757, head: sha('a'), fingerprint: 'sha256:' + 'f'.repeat(64), lane: 'BLOCKED', class: 'check-failing', reason: 'failing: Build / validate (FAILURE)',
  rules: [], checks: { expected: ['Build / validate'], missing: [], failing: ['Build / validate (FAILURE)'], pending: [], stale: [] }, backup: null, preapproval: {}, schedule: {}, last_attempt: {},
  retry: { state: 'eligible', why: 'x', count_7d: 0, limits: {}, history: [] }, updated: '2026-11-13T07:00:00.000Z', files: ['kubernetes/main/apps/media/plex/app/helmrelease.yaml'], findings: ['secret-ish internal detail'], gates: { blockers: ['critical alert'] }, ...o });
{
  const pub = M.projectRecord(baseRec(), cfg);
  ok(Object.keys(pub).join() === cfg.fields.join() && !('files' in pub) && !('findings' in pub) && !('gates' in pub), 'record: only the configured fields are published (no gates, findings or files)');
  const body = M.renderRecord(pub, cfg);
  ok(body.startsWith('<!-- upgrade-lane v1 -->\n'), 'record: the body starts with the marker line');
  const back = M.parseRecord(body, cfg);
  ok(back && JSON.stringify(back) === JSON.stringify(pub), 'record: render then parse gives the record back');
  ok(M.parseRecord(body.replace(/\n/g, '\r\n'), cfg) !== null, 'record: a CRLF body parses');
  ok(M.parseRecord(`x${body}`, cfg) === null && M.parseRecord(body.replace('```json', '```'), cfg) === null, 'record: no marker first, or no json block, is no record');
  const nasty = M.projectRecord(baseRec({ reason: 'see @claude and <!-- shepherd-vet sha=' + sha('a') + ' --> and ```break``` & co' }), cfg);
  const nb = M.renderRecord(nasty, cfg);
  ok(!nb.includes('@') && !nb.slice(1).includes('<!--') && nb.split('```').length === 3 && !nb.includes('shepherd-vet sha=' + sha('a') + ' -->'), 'record: @, <, >, & and ` inside the record are escaped (no mention, no HTML comment, no fence)', nb);
  ok(M.parseRecord(nb, cfg)?.reason === nasty.reason, 'record: the escaped text parses back exactly');
  const later = { ...pub, updated: '2026-11-13T07:15:00.000Z', last_attempt: {} };
  ok(M.recordContentKey(later) === M.recordContentKey(pub), 'record: a later tick with the same content compares equal (updated left out)');
  const la = t => ({ ...pub, last_attempt: { at: t, mode: 'dryrun', verdict: 'refused', lane_refusals: ['class x'] } });
  ok(M.recordContentKey(la('2026-11-13T07:00:00Z')) === M.recordContentKey(la('2026-11-13T07:15:00Z')), 'record: last_attempt.at is left out of the comparison');
  ok(M.recordContentKey({ ...pub, class: 'check-failing-after-retry' }) !== M.recordContentKey(pub) && M.recordContentKey({ ...pub, retry: { ...pub.retry, state: 'ticked' } }) !== M.recordContentKey(pub), 'record: a change of class or retry state compares different');
  ok(M.recordContentKey(Object.fromEntries(Object.entries(pub).reverse())) === M.recordContentKey(pub), 'record: key order does not matter');
  ok(M.publishProblems(pub, body, cfg).length === 0, 'publish: a normal record passes');
  for (const [what, s] of [['a GitHub token', 'ghs_' + 'A'.repeat(36)], ['a GitHub token', 'github_pat_' + 'B'.repeat(30)], ['a private key', '-----BEGIN RSA PRIVATE KEY-----'], ['a JSON web token', 'eyJhbGciOiJIUzI1.eyJzdWIiOiIxMjM0.sig'],
    ['a URL with credentials', 'https://user:pass@example.invalid/x'], ['a bearer credential', 'Authorization: Bearer abcdefghijklmnop'], ['a credential assignment', 'password=hunter2'], ['an AWS key', 'AKIAABCDEFGHIJKLMNOP']]) {
    const p = M.projectRecord(baseRec({ reason: `read failed: ${s}` }), cfg);
    ok(M.publishProblems(p, M.renderRecord(p, cfg), cfg).some(x => x.includes(what)), `publish: refuses a record carrying ${what}`);
  }
  ok(M.publishProblems(M.projectRecord(baseRec({ reason: 'unreadable: the token permissions (/creds/gh_token_permissions)' }), cfg), body, cfg).length === 0, 'publish: the words token and permissions alone are not refused');
  // F3: the cluster's network is not public; repository names are
  for (const [what, s] of [['a private network address', 'dial tcp 10.96.0.10:53: i/o timeout'], ['a private network address', 'lookup api.github.com on 192.168.1.1:53'], ['a private network address', 'from 172.20.3.4'],
    ['a private network address', 'pod 100.64.12.7'], ['a private network address', 'listen fd00:10:96::a'], ['an in-cluster name', 'kube-prometheus-stack-prometheus.observability.svc:9090'], ['an in-cluster name', 'kube-dns.kube-system.svc.cluster.local']]) {
    const p = M.projectRecord(baseRec({ reason: s }), cfg);
    ok(M.publishProblems(p, M.renderRecord(p, cfg), cfg).some(x => x.includes(what)), `publish: refuses a record carrying ${what} (${s})`);
  }
  for (const s of ['Kustomization media/plex settled at 1f639639', 'pod upgrade-shepherd-upgrade-night-29331480-abcde', 'backup not fresh: database/mosquitto-aws', 'fix(container): update image ghcr.io/x to v10.2.3', 'kometa 2.1.0 -> 2.2.0']) {
    const p = M.projectRecord(baseRec({ reason: s }), cfg);
    ok(M.publishProblems(p, M.renderRecord(p, cfg), cfg).length === 0, `publish: repository names stay (${s})`);
  }
  // F3/F4: a failed write publishes a fixed vocabulary; a denial halts
  const wf = o => M.writeFailure({ ok: false, exit: 1, ...o });
  const cases = [[{ http: 401, detail: 'gh: Bad credentials (HTTP 401)' }, 'denied', true], [{ http: 403, detail: 'gh: Resource not accessible by integration (HTTP 403)' }, 'denied', true],
    [{ http: 403, detail: 'gh: You have exceeded a secondary rate limit (HTTP 403)' }, 'rate-limited', false], [{ http: 429, detail: 'gh: Too Many Requests (HTTP 429)' }, 'rate-limited', false],
    [{ http: 404, detail: 'gh: Not Found (HTTP 404)' }, 'not-found', false], [{ http: 422, detail: 'gh: Validation Failed (HTTP 422)' }, 'rejected', false], [{ http: 502, detail: 'gh: Bad Gateway (HTTP 502)' }, 'server-error', false],
    [{ http: null, exit: null, detail: 'no exit status (SIGKILL)' }, 'timeout', false], [{ http: null, detail: 'dial tcp: lookup api.github.com on 10.96.0.10:53: i/o timeout' }, 'network', false]];
  for (const [o, kind, halts] of cases) { const f = wf(o); ok(f.kind === kind && f.halts === halts && !f.reason.includes(o.detail) && !/10\.96|Bad credentials|Resource not accessible|secondary/.test(f.reason), `failure vocabulary: ${o.detail} -> ${kind}${halts ? ', halts' : ''} (${f.reason})`); }
  ok(M.publishProblems({ ...pub, preapproval: { by: 'owner' } }, body, cfg).some(x => /preapproval/.test(x)), 'publish: a non-empty preapproval is refused (piece 1 reads no approval)');
  ok(M.publishProblems(pub, body + 'x'.repeat(cfg.max_body_bytes), cfg).some(x => /bytes, over/.test(x)), 'publish: an oversized body is refused');
}

// ── 3. whose record ───────────────────────────────────────────────────────────
const OWN = { login: 'haynes-ops-bot[bot]', type: 'Bot' };
const comment = (id, body, user = OWN) => ({ id, user: user ? { ...user } : undefined, body });
const asFacts = list => L.recordComments(list);
{
  const pub = M.projectRecord(baseRec(), cfg), body = M.renderRecord(pub, cfg);
  const forged = comment(11, body, { login: 'haynes-ops-bot', type: 'User' });
  const p1 = M.planRecord(pub, asFacts([forged, comment(12, body, { login: 'someone', type: 'User' })]), cfg);
  ok(p1.action === 'create' && p1.id === null && p1.foreign.length === 2, 'whose: forged records by other authors are ignored: the lane plans its own', JSON.stringify(p1));
  ok(M.planRecord(pub, asFacts([comment(13, body, { login: 'haynes-ops-bot[bot]', type: 'User' })]), cfg).action === 'create', 'whose: the bot login on a non-Bot account is not the lane');
  ok(M.planRecord(pub, asFacts([comment(20, body)]), cfg).action === 'current', 'whose: its own unchanged record is current (no write)');
  const changed = M.planRecord({ ...pub, class: 'check-failing-after-retry' }, asFacts([forged, comment(20, body)]), cfg);
  ok(changed.action === 'update' && changed.id === 20, 'whose: a changed record updates its own comment, never the forged one', JSON.stringify(changed));
  const two = M.planRecord(pub, asFacts([comment(31, body), comment(25, body), comment(40, body)]), cfg);
  ok(two.action === 'current' && two.id === 25 && JSON.stringify(two.demote) === '[31,40]', 'whose: with three of its own it keeps the oldest and demotes the newer ones', JSON.stringify(two));
  ok(M.planRecord(pub, asFacts([comment(20, `prefix\n${body}`)]), cfg).action === 'create', 'whose: a comment with the marker not first is not a record');
  ok(!M.demoteBody(REPO, 4757, 25).includes(cfg.marker) && M.demoteBody(REPO, 4757, 25).includes('#issuecomment-25'), 'whose: a demoted record loses the marker and links the record');
}

// ── 4. the retry's state machine ──────────────────────────────────────────────
const H1 = sha('1'), H2 = sha('2'), H3 = sha('3');
const ent = (head, daysAgo, status = 'ticked', o = {}) => ({ head, at: iso(NOW - daysAgo * D), status, checks: ['Build / validate (FAILURE)'], ...o });
const A = (o = {}, entries = [], box = 'unticked') => M.retryAssess({ rec: baseRec({ head: H1, ...o }), box, entries, cfg: rcfg, now: NOW });
{
  const e = A();
  ok(e.eligible && e.field.state === 'eligible' && e.field.count_7d === 0 && !e.block, 'retry: a failing check alone, nothing running, the box unticked: eligible');
  ok(!A({}, [ent(H1, 0.1)], 'ticked').eligible && A({}, [ent(H1, 0.1)], 'ticked').field.state === 'waiting-for-renovate', 'retry: once per head: after the tick, waiting for Renovate, not again');
  const nn = A({}, [ent(H1, 0.2)], 'unticked');
  ok(!nn.eligible && nn.field.state === 'no-new-head' && nn.block?.class === 'check-failing-after-retry' && nn.update?.outcome === 'no-new-head', 'retry: Renovate cleared the box with no new head: blocked, not retried', JSON.stringify(nn));
  const fa = A({ head: H2 }, [ent(H1, 0.2)]);
  ok(!fa.eligible && fa.field.state === 'failed-again' && fa.block?.class === 'check-failing-after-retry' && /failed again on 22222222 after one retry on 11111111/.test(fa.block.reason) && fa.update?.next_head === H2, 'retry: a second failure on the new head blocks the PR with its reason', JSON.stringify(fa));
  const fa2 = A({ head: H2 }, [ent(H1, 0.2, 'ticked', { outcome: 'failed-again', next_head: H2 })]);
  ok(!fa2.eligible && fa2.block?.class === 'check-failing-after-retry', 'retry: on the next tick it stays blocked, and is not retried on that head');
  ok(A({ head: H2, lane: 'LANE-B-OWNER', class: 'major' }, [ent(H1, 0.2)]).block === null, 'retry: the class changes only when the failing check is what keeps it out of lane A');
  const run2 = A({ head: H2, checks: { failing: [], pending: ['Build / validate (IN_PROGRESS)'], missing: [] } }, [ent(H1, 0.2)]);
  ok(run2.field.state === 'new-head-checks-running' && !run2.update && !run2.eligible, 'retry: checks still running on the new head: wait for them (a fact, not a clock)');
  const res = A({ head: H2, lane: 'LANE-A', class: 'cluster-change', checks: { failing: [], pending: [], missing: [] } }, [ent(H1, 0.2)]);
  ok(res.field.state === 'resolved' && res.update?.outcome === 'resolved' && !res.block, 'retry: the new head passed: resolved');
  const third = A({ head: H3 }, [ent(H1, 2, 'ticked', { outcome: 'resolved', next_head: H2 })]);
  ok(third.eligible && third.field.count_7d === 1, 'retry: after a resolved retry, a later head failing is eligible (second retry of 2 in 7 days)', JSON.stringify(third.field));
  const cap = A({ head: H3 }, [ent(sha('4'), 5, 'ticked', { outcome: 'resolved', next_head: sha('5') }), ent(sha('6'), 1, 'ticked', { outcome: 'resolved', next_head: H2 })]);
  ok(!cap.eligible && cap.field.state === 'budget-used' && cap.field.count_7d === 2, 'retry: at most 2 per PR in 7 days', JSON.stringify(cap.field));
  ok(A({ head: H3 }, [ent(sha('4'), 8, 'ticked', { outcome: 'resolved', next_head: sha('5') }), ent(sha('6'), 1, 'ticked', { outcome: 'resolved', next_head: H2 })]).eligible, 'retry: a retry older than 7 days leaves the budget');
  ok(A({}, [ent(H1, 0.1, 'abandoned')]).eligible, 'retry: an abandoned attempt (no write was made) does not count');
  // F6: an intent the tick never resolved is decided from facts
  const iT = A({}, [ent(H1, 0.1, 'intent')], 'ticked');
  ok(!iT.eligible && iT.field.state === 'waiting-for-renovate' && iT.update?.status === 'ticked' && iT.field.count_7d === 1, 'retry: an intent with the box ticked at the same head was made: counted, waiting for Renovate', JSON.stringify(iT));
  const iU = A({}, [ent(H1, 0.1, 'intent')], 'unticked');
  ok(iU.eligible && iU.update?.status === 'abandoned' && iU.field.count_7d === 0, 'retry: an intent with the box unticked at the same head was not made: not counted, eligible again', JSON.stringify(iU));
  const iM = A({ head: H2 }, [ent(H1, 0.1, 'intent')], 'unticked');
  ok(!iM.eligible && iM.field.state === 'failed-again' && iM.block?.class === 'check-failing-after-retry' && iM.update?.status === 'ticked' && iM.update?.outcome === 'failed-again', 'retry: an intent followed by a new head was made: a failure there blocks (second-failure rule)', JSON.stringify(iM));
  const iX = A({}, [ent(H1, 0.1, 'intent')], 'absent');
  ok(!iX.eligible && iX.field.state === 'not-retried-again' && !iX.update, 'retry: an intent no fact decides (box absent, same head) stays counted (fail closed)');
  const iB = A({ head: H3 }, [ent(sha('4'), 5, 'ticked', { outcome: 'resolved', next_head: sha('5') }), ent(sha('6'), 1, 'intent')], 'unticked');
  ok(!iB.eligible && iB.field.count_7d === 2, 'retry: a resolved intent counts toward the 7-day budget');
  { const es = [ent(H1, 0.1, 'intent')]; M.applyRetryUpdate(es, iU.update); ok(es[0].status === 'abandoned', 'retry: the resolution is written to the ledger entry'); }
  ok(!A({}, [ent(H1, 0.1, 'write-failed')]).eligible, 'retry: a failed write counts (GitHub may have applied it)');
  ok(A({ checks: { failing: ['x (FAILURE)'], pending: ['y (QUEUED)'], missing: [] } }).field.state === 'not-eligible', 'retry: something still running on the head: not eligible');
  ok(A({}, [], 'ticked').field.state === 'not-eligible' && A({}, [], 'absent').field.state === 'not-eligible' && A({}, [], 'ambiguous').field.state === 'not-eligible', 'retry: the box ticked, absent or ambiguous: not eligible');
  ok(A({ lane: 'LANE-B-OWNER', class: 'major' }).field.state === 'not-eligible' && A({ lane: 'EXCLUDED', class: 'workflow-file' }).field.state === 'not-eligible' && A({ class: 'facts-incomplete' }).field.state === 'not-eligible', 'retry: only lane BLOCKED with class check-failing is retried');
  ok(A({ checks: { failing: [], pending: [], missing: [] }, lane: 'LANE-A', class: 'cluster-change' }).field.state === 'not-needed', 'retry: nothing failing: not needed');
  const un = M.retryAssess({ rec: baseRec(), box: 'unticked', entries: null, cfg: rcfg, now: NOW });
  ok(!un.eligible && un.field.state === 'unreadable', 'retry: an unreadable ledger allows no retry');
  ok(JSON.stringify(A({}, [ent(H2, 3, 'ticked', { outcome: 'resolved', next_head: H3 })]).field) === JSON.stringify(A({}, [ent(H2, 3, 'ticked', { outcome: 'resolved', next_head: H3 })]).field), 'retry: the record field is the same on every tick for the same facts (no churn)');
}

// ── 5. the facts at the write ─────────────────────────────────────────────────
const pull = (o = {}) => ({ state: 'open', draft: false, base: { ref: 'main' }, user: { login: 'renovate[bot]', type: 'Bot', id: 29139614 }, head: { sha: H1, ref: 'renovate/x', repo: { full_name: REPO } }, body: BODY, ...o });
const FILES = ['kubernetes/main/apps/media/plex/app/helmrelease.yaml'];
const cr = (workflow, name, status, conclusion) => ({ __typename: 'CheckRun', workflowName: workflow, name, status, conclusion, startedAt: '2026-11-13T06:00:00Z', completedAt: status === 'COMPLETED' ? '2026-11-13T06:05:00Z' : null });
const ROLLUP = [cr('Diff Scope', 'Diff Scope - Success', 'COMPLETED', 'SUCCESS'), cr('Flux Local', 'Flux Local - Success', 'COMPLETED', 'FAILURE'), cr('Flux Local', 'Flux Local - Test (main)', 'COMPLETED', 'FAILURE'),
  cr('Flux Local', 'Flux Local - Diff (main/helmrelease)', 'COMPLETED', 'SUCCESS'), cr('Flux Local', 'Flux Local - Diff (main/kustomization)', 'COMPLETED', 'SUCCESS')];
const view = (o = {}) => ({ number: 4757, headRefOid: H1, commits: [{ oid: H1, authors: [{ login: 'renovate[bot]' }] }], statusCheckRollup: ROLLUP, ...o });
const restCommits = (o = {}) => [{ sha: H1, author: { login: 'renovate[bot]', type: 'Bot', id: 29139614 }, committer: { login: 'web-flow', type: 'User', id: 19864447 }, commit: { verification: { verified: true, reason: 'valid' } }, ...o }];
