// A fake GitHub: comments per PR; write() records the call and applies it.
function fakeGitHub({ failOn = null, identity = OWN } = {}) {
  const store = new Map(); let nextId = 100; const writes = [];
  const reads = [];
  const run = (cmd, argv) => {
    reads.push(argv.join(' '));
    const p = argv.find(a => a.startsWith('repos/'));
    let m;
    if ((m = /issues\/(\d+)\/comments/.exec(p))) return JSON.stringify([store.get(Number(m[1])) || []]);
    if ((m = /issues\/comments\/(\d+)$/.exec(p))) { for (const list of store.values()) { const c = list.find(x => x.id === Number(m[1])); if (c) return JSON.stringify(c); } return null; }
    return null;
  };
  const write = (kind, a) => {
    writes.push({ kind, ...a });
    if (failOn && failOn(kind, a)) { const f = failOn(kind, a); return { ok: false, http: f.http ?? 403, detail: f.detail ?? 'gh: Resource not accessible by integration (HTTP 403)', call: `gh api ${kind}` }; }
    if (kind === 'record-create') { const c = { id: nextId++, user: { ...identity }, body: a.body }; store.set(a.pr, [...(store.get(a.pr) || []), c]); return { ok: true, json: c, call: 'create' }; }
    for (const list of store.values()) { const c = list.find(x => x.id === a.commentId); if (c) { c.body = a.body; return { ok: true, json: c, call: 'edit' }; } }
    return { ok: false, http: 404, detail: 'Not Found', call: 'edit' };
  };
  const items = recs => recs.map(rec => ({ rec, comments: L.recordComments(store.get(rec.pr) || []) }));
  return { store, writes, reads, run, write, items };
}
